"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["66303"],{36070(e){e.exports=JSON.parse('{"id":"FIN-767","slug":"demand-pull-inflation","term":"Demand-Pull Inflation","also_known_as":[],"difficulty":"Intermediate","definition":"Demand-pull inflation is inflation caused by total demand for goods and services in an economy growing faster than the economy\'s ability to produce them.","explanation":["Demand-pull inflation is often described as too much money chasing too few goods. When households, businesses and governments together want to buy more than the economy can supply, sellers can raise prices.","Demand can rise for many reasons: strong consumer confidence, rising incomes, low interest rates that encourage borrowing, increased government spending, tax cuts or strong demand for exports.","For example, if interest rates are cut and the government also increases spending at a time when unemployment is already low, businesses may struggle to keep up with demand. With few spare workers and limited production capacity, they raise prices and wages, pushing up inflation.","Demand-pull inflation is typically addressed by reducing demand. Central banks may raise interest rates, making borrowing more expensive and encouraging saving. Governments may cut spending or raise taxes. This differs from cost-push inflation, which is driven by rising production costs rather than excess demand and can be harder to tackle without hurting growth."],"note":"","total":1500,"prev":{"slug":"demand-deposit","term":"Demand Deposit"},"next":{"slug":"demographic-dividend","term":"Demographic Dividend"}}')}}]);